import { GoogleGenAI, FunctionDeclaration, Type } from "@google/genai";

// Tool definition for saving leads
const saveLeadTool: FunctionDeclaration = {
  name: 'saveLead',
  parameters: {
    type: Type.OBJECT,
    description: 'Salva os dados de um cliente potencial (lead) no banco de dados quando ele demonstra interesse em contratar a agência.',
    properties: {
      name: { type: Type.STRING, description: 'Nome do cliente' },
      company: { type: Type.STRING, description: 'Nome da empresa' },
      phone: { type: Type.STRING, description: 'Telefone ou WhatsApp do cliente' },
      revenue: { type: Type.STRING, description: 'Faturamento mensal estimado da empresa' },
      needs: { type: Type.STRING, description: 'Resumo da necessidade do cliente' }
    },
    required: ['name', 'phone', 'company'],
  },
};

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export const generateAIResponse = async (history: ChatMessage[]): Promise<{ text: string, functionCall?: any }> => {
  try {
    const apiKey = typeof process !== 'undefined' && process.env ? process.env.API_KEY : undefined;

    if (!apiKey) {
      return { text: "⚠️ Configuração de API ausente." };
    }

    const ai = new GoogleGenAI({ apiKey: apiKey });

    const systemInstruction = `
      Você é a IA de Vendas da BF Agência (Gestão de Tráfego).

      SEU OBJETIVO:
      1. Identificar se o usuário é "CURIOSO" ou "CLIENTE POTENCIAL".
      2. Se for CURIOSO (perguntas genéricas, dicas grátis): Responda de forma breve, útil, mas encerre convidando para conhecer os serviços pagos.
      3. Se for CLIENTE POTENCIAL (quer contratar, quer saber preço, quer crescer): Inicie a qualificação IMEDIATAMENTE.

      PROCESSO DE QUALIFICAÇÃO (Faça perguntas uma por uma, seja natural):
      - Pergunte o Nome e a Empresa.
      - Pergunte o Faturamento Médio Mensal (para sabermos o porte).
      - Pergunte o WhatsApp para contato.

      FINALIZAÇÃO:
      Assim que tiver Nome, Empresa, Telefone e uma ideia do Faturamento, CHAME A FUNÇÃO 'saveLead' com os dados.
      Não peça para o usuário clicar em nada antes de você chamar a função. Apenas diga "Vou registrar seu interesse..." e chame a função.

      Tom de voz: Profissional, confiante, direto (estilo "Lobo de Wall Street" mas educado).
      Não use textos longos.
    `;

    // Convert internal history format to Gemini format
    const contents = history.map(msg => ({
      role: msg.role,
      parts: [{ text: msg.text }]
    }));

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: contents,
      config: {
        systemInstruction: systemInstruction,
        tools: [{ functionDeclarations: [saveLeadTool] }],
      }
    });

    const candidate = response.candidates?.[0];
    const modelText = candidate?.content?.parts?.find(p => p.text)?.text || "";

    // Check for function calls
    const functionCall = candidate?.content?.parts?.find(p => p.functionCall)?.functionCall;

    return {
      text: modelText,
      functionCall: functionCall
    };

  } catch (error) {
    console.error("Erro na Gemini API:", error);
    return { text: "Estou enfrentando uma instabilidade momentânea. Por favor, me chame no WhatsApp." };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { X, Send, Bot, MessageCircle } from 'lucide-react';
import { generateAIResponse, ChatMessage } from '../services/geminiService';
import { saveLead } from '../services/firebase';

export const AIChat: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Olá! Sou a IA da BF Agência. Você quer escalar as vendas da sua empresa ou apenas tirar dúvidas?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [leadSaved, setLeadSaved] = useState(false);
  const [whatsappLink, setWhatsappLink] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(scrollToBottom, [messages, isLoading, leadSaved]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg = input;
    setInput('');
    const newHistory = [...messages, { role: 'user', text: userMsg } as ChatMessage];
    setMessages(newHistory);
    setIsLoading(true);

    try {
      const { text, functionCall } = await generateAIResponse(newHistory);

      if (functionCall && functionCall.name === 'saveLead') {
        // AI decided to save the lead
        const args = functionCall.args;

        // Save to Firebase
        await saveLead({
            ...args,
            source: 'chatbot_qualification'
        });

        // Generate confirmation text
        const confirmText = "Perfeito! Já registrei seus dados no nosso sistema. Para agilizar seu atendimento, clique no botão abaixo para falar diretamente com nosso especialista no WhatsApp.";
        setMessages(prev => [...prev, { role: 'model', text: confirmText }]);

        // Setup WhatsApp Button
        const waText = `Olá! Vim pelo Chatbot do site. Me chamo ${args.name}, da empresa ${args.company}.`;
        setWhatsappLink(`https://wa.me/5573991002247?text=${encodeURIComponent(waText)}`);
        setLeadSaved(true);

        // Also trigger email mailto for redundancy as requested
        const mailtoUrl = `mailto:bfagencia1@gmail.com?subject=Lead via Chatbot - ${args.company}&body=Dados capturados pelo bot:%0D%0ANome: ${args.name}%0D%0AEmpresa: ${args.company}%0D%0AFone: ${args.phone}`;
        window.location.href = mailtoUrl;

      } else {
        // Normal text response
        setMessages(prev => [...prev, { role: 'model', text: text || "Entendido." }]);
      }

    } catch (e) {
      console.error(e);
      setMessages(prev => [...prev, { role: 'model', text: 'Desculpe, tive um erro de conexão. Por favor, use o botão do WhatsApp no canto da tela.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Trigger Button */}
      <button 
        onClick={() => setIsOpen(true)} 
        className={`fixed bottom-24 right-5 z-[90] bg-zinc-800 hover:bg-zinc-700 text-white p-3 rounded-full shadow-lg border border-brand-yellow/30 transition-all duration-300 ${isOpen ? 'opacity-0 pointer-events-none' : 'opacity-100 scale-100'}`}
        title="Falar com IA"
      >
        <Bot size={24} className="text-brand-yellow" />
      </button>

      {/* Chat Window */}
      <div className={`fixed bottom-5 right-5 sm:bottom-24 sm:right-5 z-[99] w-[90vw] sm:w-[350px] bg-[#0a0a0a] border border-zinc-800 rounded-2xl shadow-2xl overflow-hidden transition-all duration-300 origin-bottom-right ${isOpen ? 'scale-100 opacity-100 translate-y-0' : 'scale-95 opacity-0 translate-y-10 pointer-events-none'}`}>
        {/* Header */}
        <div className="bg-zinc-900 p-4 flex justify-between items-center border-b border-zinc-800">
          <div className="flex items-center gap-2">
            <Bot className="text-brand-yellow" size={20} />
            <span className="font-heading font-bold text-white text-sm">BF Intelligence</span>
          </div>
          <button onClick={() => setIsOpen(false)} className="text-gray-400 hover:text-white">
            <X size={18} />
          </button>
        </div>

        {/* Messages */}
        <div className="h-[300px] overflow-y-auto p-4 space-y-3 bg-black/90">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-3 rounded-lg text-sm ${msg.role === 'user' ? 'bg-brand-yellow text-black rounded-tr-none' : 'bg-zinc-800 text-gray-200 rounded-tl-none'}`}>
                {msg.text}
              </div>
            </div>
          ))}

          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-zinc-800 p-3 rounded-lg rounded-tl-none flex gap-1">
                <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce delay-100"></div>
                <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce delay-200"></div>
              </div>
            </div>
          )}

          {/* CTA for Saved Lead */}
          {leadSaved && (
             <div className="flex justify-center mt-4">
                <a 
                  href={whatsappLink} 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="bg-[#25D366] text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-[#128C7E] transition-colors animate-pulse"
                >
                  <MessageCircle size={18} />
                  Finalizar no WhatsApp
                </a>
             </div>
          )}

          <div ref={messagesEndRef} />
        </div>

        {/* Input */}
        <div className="p-3 bg-zinc-900 border-t border-zinc-800 flex gap-2">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            disabled={leadSaved} // Disable input after conversion to force WA
            placeholder={leadSaved ? "Atendimento transferido para WhatsApp" : "Digite sua mensagem..."}
            className="flex-1 bg-black border border-zinc-700 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-brand-yellow disabled:opacity-50"
          />
          <button 
            onClick={handleSend} 
            disabled={leadSaved}
            className="bg-brand-yellow text-black p-2 rounded-lg hover:bg-yellow-500 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Send size={18} />
          </button>
        </div>
      </div>
    </>
  );
};

