// SUBSTITUA ESTES VALORES PELOS SEUS DO EMAILJS
const SERVICE_ID = 'service_exemplo_id'; // Ex: service_x9d8s7f
const TEMPLATE_ID = 'template_exemplo_id'; // Ex: template_k4j5h6g
const PUBLIC_KEY = 'chave_publica_exemplo'; // Ex: user_98s7df98s7df

export const sendEmailNotification = async (data: any) => {
  try {
    // Verifica se as chaves ainda são as de exemplo
    if (SERVICE_ID === 'service_exemplo_id') {
      console.warn("⚠️ EmailJS não configurado. Adicione suas chaves em services/emailService.ts");
      return;
    }

    // Mapeia os dados do seu formulário para as variáveis do Template do EmailJS
    // No seu Template do EmailJS, use {{name}}, {{company}}, {{phone}}, {{message}}
    const templateParams = {
      to_name: "Equipe BF Agência",
      from_name: data.name,
      company: data.company || "Não informada",
      phone: data.phone,
      email: data.email || "Não informado",
      revenue: data.revenue || "Não informado",
      message: data.message || data.needs || "Sem mensagem", // 'message' do form, 'needs' do chat
      source: data.source || "Site"
    };

    const response = await emailjs.send(SERVICE_ID, TEMPLATE_ID, templateParams, PUBLIC_KEY);
    console.log('✅ Email enviado com sucesso!', response.status, response.text);
    return response;
  } catch (error) {
    console.error('❌ Falha ao enviar email:', error);
    // Não lançamos o erro novamente para não travar o fluxo do WhatsApp
  }
};

import React, { useState } from 'react';
