import React, { useState, useRef, useEffect } from 'react';
import { X, Send, Bot, MessageCircle } from 'lucide-react';
import { generateAIResponse, ChatMessage } from '../services/geminiService';
import { saveLead } from '../services/firebase';
import { sendEmailNotification } from '../services/emailService';

export const AIChat: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Olá! Sou a IA da BF Agência. Você quer escalar as vendas da sua empresa ou apenas tirar dúvidas?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [leadSaved, setLeadSaved] = useState(false);
  const [whatsappLink, setWhatsappLink] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(scrollToBottom, [messages, isLoading, leadSaved]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg = input;
    setInput('');
    const newHistory = [...messages, { role: 'user', text: userMsg } as ChatMessage];
    setMessages(newHistory);
    setIsLoading(true);

    try {
      const { text, functionCall } = await generateAIResponse(newHistory);

      if (functionCall && functionCall.name === 'saveLead') {
        // AI decided to save the lead
        const args = functionCall.args;
        const leadData = {
            ...args,
            source: 'chatbot_qualification'
        };

        // 1. Save to Firebase
        try {
            await saveLead(leadData);
        } catch (e) {
             console.warn("Aviso: Falha ao salvar lead no Firebase, continuando fluxo.", e);
        }

        // 2. Send Silent Email (EmailJS)
        sendEmailNotification(leadData).catch(err => console.error("Erro email chat:", err));

        // Generate confirmation text
        const confirmText = "Perfeito! Já registrei seus dados e passei o resumo da nossa conversa para a equipe. Clique no botão abaixo para concluir o atendimento no WhatsApp.";
        setMessages(prev => [...prev, { role: 'model', text: confirmText }]);

        // Setup WhatsApp Button with RICH CONTEXT
        const waText = `*Iniciando Atendimento (Via Chatbot Site)*\n\n` +
                       `👤 *Nome:* ${args.name}\n` +
                       `🏢 *Empresa/Projeto:* ${args.company}\n` +
                       `📱 *Telefone:* ${args.phone}\n` +
                       `💰 *Faturamento/Investimento:* ${args.revenue}\n\n` +
                       `📝 *Resumo da Conversa:* \n${args.needs}`;

        const encodedText = encodeURIComponent(waText);
        // Usar wa.me para melhor compatibilidade
        setWhatsappLink(`https://wa.me/5573991002247?text=${encodedText}`);
        setLeadSaved(true);

      } else {
        // Normal text response
        setMessages(prev => [...prev, { role: 'model', text: text || "Entendido." }]);
      }

    } catch (e) {
      console.error(e);
      setMessages(prev => [...prev, { role: 'model', text: 'Desculpe, tive um erro de conexão. Por favor, use o botão do WhatsApp no canto da tela.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Trigger Button */}
      <button 
        onClick={() => setIsOpen(true)} 
        className={`fixed bottom-24 right-5 z-[90] bg-zinc-800 hover:bg-zinc-700 text-white p-3 rounded-full shadow-lg border border-brand-yellow/30 transition-all duration-300 ${isOpen ? 'opacity-0 pointer-events-none' : 'opacity-100 scale-100'}`}
        title="Falar com IA"
      >
        <Bot size={24} className="text-brand-yellow" />
      </button>

      {/* Chat Window */}
      <div className={`fixed bottom-5 right-5 sm:bottom-24 sm:right-5 z-[99] w-[90vw] sm:w-[350px] bg-[#0a0a0a] border border-zinc-800 rounded-2xl shadow-2xl overflow-hidden transition-all duration-300 origin-bottom-right ${isOpen ? 'scale-100 opacity-100 translate-y-0' : 'scale-95 opacity-0 translate-y-10 pointer-events-none'}`}>
        {/* Header */}
        <div className="bg-zinc-900 p-4 flex justify-between items-center border-b border-zinc-800">
          <div className="flex items-center gap-2">
            <Bot className="text-brand-yellow" size={20} />
            <span className="font-heading font-bold text-white text-sm">BF Intelligence</span>
          </div>
          <button onClick={() => setIsOpen(false)} className="text-gray-400 hover:text-white">
            <X size={18} />
          </button>
        </div>

        {/* Messages */}
        <div className="h-[300px] overflow-y-auto p-4 space-y-3 bg-black/90">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-3 rounded-lg text-sm ${msg.role === 'user' ? 'bg-brand-yellow text-black rounded-tr-none' : 'bg-zinc-800 text-gray-200 rounded-tl-none'}`}>
                {/* Check if text contains a link (simple heuristic) */}
                {msg.text.includes('https://wa.me') || msg.text.includes('api.whatsapp.com') ? (
                    <span>
                        {msg.text.split(/https:\/\/(wa\.me|api\.whatsapp\.com)/)[0]}
                        <a href="https://wa.me/5573991002247" target="_blank" rel="noopener noreferrer" className="underline font-bold text-brand-yellow hover:text-white">
                            Clique aqui para chamar no WhatsApp
                        </a>
                    </span>
                ) : (
                    msg.text
                )}
              </div>
            </div>
          ))}

          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-zinc-800 p-3 rounded-lg rounded-tl-none flex gap-1">
                <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce delay-100"></div>
                <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce delay-200"></div>
              </div>
            </div>
          )}

          {/* CTA for Saved Lead */}
          {leadSaved && (
             <div className="flex justify-center mt-4 pb-2">
                <a 
                  href={whatsappLink} 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="bg-[#25D366] text-white px-6 py-3 rounded-lg font-bold flex items-center gap-2 hover:bg-[#128C7E] transition-colors animate-pulse shadow-lg hover:scale-105 transform"
                >
                  <MessageCircle size={20} />
                  Continuar no WhatsApp
                </a>
             </div>
          )}

          <div ref={messagesEndRef} />
        </div>

        {/* Input */}
        <div className="p-3 bg-zinc-900 border-t border-zinc-800 flex gap-2">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            disabled={leadSaved} 
            placeholder={leadSaved ? "Atendimento transferido para WhatsApp" : "Digite sua mensagem..."}
            className="flex-1 bg-black border border-zinc-700 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-brand-yellow disabled:opacity-50"
          />
          <button 
            onClick={handleSend} 
            disabled={leadSaved}
            className="bg-brand-yellow text-black p-2 rounded-lg hover:bg-yellow-500 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Send size={18} />
          </button>
        </div>
      </div>
    </>
  );
};

import { GoogleGenAI, FunctionDeclaration, Type } from "@google/genai";

// Tool definition for saving leads
const saveLeadTool: FunctionDeclaration = {
  name: 'saveLead',
  parameters: {
    type: Type.OBJECT,
    description: 'Salva os dados de um cliente potencial (lead) no banco de dados quando ele demonstra interesse. Deve ser chamado ao final da qualificação.',
    properties: {
      name: { type: Type.STRING, description: 'Nome do cliente' },
      company: { type: Type.STRING, description: 'Nome da empresa ou "Projeto Pessoal" se não tiver empresa.' },
      phone: { type: Type.STRING, description: 'Telefone ou WhatsApp do cliente' },
      revenue: { type: Type.STRING, description: 'Faturamento mensal estimado (ou "Iniciante" se não tiver)' },
      needs: { type: Type.STRING, description: 'RESUMO COMPLETO da conversa: O que o cliente quer? Qual a dor dele? (Ex: "Quer crescer instagram pessoal", "Tem loja de roupas e quer vender mais")' }
    },
    required: ['name', 'phone', 'company', 'needs'],
  },
};

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

// Declaração para evitar erros de TypeScript, já que o Vite fará a substituição via define
declare global {
  var process: {
    env: {
      API_KEY: string;
    };
  };
}

export const generateAIResponse = async (history: ChatMessage[]): Promise<{ text: string, functionCall?: any }> => {
  try {
    // Correção: Acessar diretamente process.env.API_KEY.
    // O Vite substitui "process.env.API_KEY" pelo valor da string durante o build.
    // A verificação anterior (typeof process !== 'undefined') falhava no browser pois o objeto 'process' não existe nativamente.
    const apiKey = process.env.API_KEY;

    if (!apiKey) {
      console.error("API_KEY não encontrada. Verifique o arquivo .env ou as variáveis de ambiente da Vercel.");
      return { text: "⚠️ Configuração de API ausente." };
    }

    const ai = new GoogleGenAI({ apiKey: apiKey });

    const systemInstruction = `
      Você é a IA de Vendas da BF Agência (Gestão de Tráfego).

      SEU OBJETIVO:
      Qualificar e coletar dados de QUALQUER pessoa interessada em crescer no digital.

      REGRAS CRITICAS:
      1. **CLIENTE SEM EMPRESA É CLIENTE**: Se o usuário disser "Não tenho empresa", NÃO O DESCARTE. Trate como um projeto de "Marca Pessoal", "Influenciador" ou "Negócio em fase de ideia". Pergunte qual o objetivo dele (Ex: "Quer crescer seu perfil pessoal?", "Quer lançar um produto?").
      2. **QUALIFICAÇÃO**:
         - Nome
         - Nome do Projeto/Empresa (Se não tiver, chame de "Projeto Pessoal")
         - WhatsApp
         - Faturamento (Se for pessoa física/iniciante, pergunte quanto pretende investir ou se está começando do zero).
      3. **PEDIDO DE NÚMERO**: Se o usuário pedir especificamente "me passa o zap", "quero o número" ou "falar com humano" AGORA, forneça o link https://wa.me/5573991002247 IMEDIATAMENTE.

      FINALIZAÇÃO (Use a ferramenta 'saveLead'):
      - Assim que tiver os dados básicos, chame a função 'saveLead'.
      - No campo 'needs' da função, faça um RESUMO do que o cliente falou. Não coloque apenas "tráfego". Coloque: "Cliente quer anunciar perfil pessoal de nutrição", ou "Cliente vai abrir loja mês que vem".
      - Após chamar a função, diga: "Perfeito, [Nome]. Registrei seu interesse e nosso especialista já vai analisar seu caso. Clique no botão abaixo para finalizar."

      Tom de voz: Profissional, "Lobo de Wall Street", mas adaptável. Se o cliente não tem empresa, seja encorajador ("Vamos construir esse império do zero").
    `;

    // Convert internal history format to Gemini format
    const contents = history.map(msg => ({
      role: msg.role,
      parts: [{ text: msg.text }]
    }));

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: contents,
      config: {
        systemInstruction: systemInstruction,
        tools: [{ functionDeclarations: [saveLeadTool] }],
      }
    });

    const candidate = response.candidates?.[0];
    const modelText = candidate?.content?.parts?.find(p => p.text)?.text || "";

    // Check for function calls
    const functionCall = candidate?.content?.parts?.find(p => p.functionCall)?.functionCall;

    return {
      text: modelText,
      functionCall: functionCall
    };

  } catch (error) {
    console.error("Erro na Gemini API:", error);
    return { text: "Estou enfrentando uma instabilidade momentânea. Por favor, me chame no WhatsApp." };
  }
};

